pub mod oneshot {
    use verus_builtin::*;
    use verus_builtin_macros::*;
    use vstd::prelude::*;
    use vstd::resource::algebra::ResourceAlgebra;
    use vstd::resource::pcm;
    use vstd::resource::pcm::PCM;
